using System;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Interop;
using AirBridge.UI;
using AirBridge.Platform;
namespace AirBridge.Desktop {
 internal sealed partial class MainView {
  Window trayPanel;
  void CloseTrayPanel(){if(trayPanel!=null)trayPanel.Close();}
  void ShowTrayPanel(){if(trayPanel!=null){CloseTrayPanel();return;}var w=BuildTrayPanel();trayPanel=w;var anchor=System.Windows.Forms.Cursor.Position;w.Opacity=0;w.SourceInitialized+=(s,e)=>WindowWorkArea.PositionTray(w,anchor,false);w.ContentRendered+=(s,e)=>{WindowWorkArea.PositionTray(w,anchor,true);w.Opacity=1;w.BeginAnimation(UIElement.OpacityProperty,Motion.Tween(0,1,160));w.Activate();};w.Deactivated+=(s,e)=>w.Close();w.PreviewKeyDown+=(s,e)=>{if(e.Key==Key.Escape)w.Close();};w.Closed+=(s,e)=>{if(trayPanel==w)trayPanel=null;};w.Show();}
  Button TrayAction(string text,int icon,Action action){var b=Button("",()=>{CloseTrayPanel();action();});b.Content=Glyph(icon,text);((TextBlock)((StackPanel)b.Content).Children[0]).Margin=new Thickness(0,0,8,0);b.SetResourceReference(FrameworkElement.StyleProperty,"TrayAction");((TextBlock)((StackPanel)b.Content).Children[0]).Foreground=Brush("#5887E8");b.HorizontalContentAlignment=HorizontalAlignment.Center;b.Height=40;b.Padding=new Thickness(8,0,8,0);b.VerticalContentAlignment=VerticalAlignment.Center;return b;}
  void TrayRule(Panel host){var line=new Border{Height=1,Margin=new Thickness(0,12,0,12)};line.SetResourceReference(Border.BackgroundProperty,"Brush_E8EBF0");host.Children.Add(line);}
  void TrayDevice(Panel host,string name,string status,int icon,string id,Action action){
   var body=new Grid();body.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(30)});body.ColumnDefinitions.Add(new ColumnDefinition());body.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});
   var glyph=new TextBlock{Text=Char.ConvertFromUtf32(icon),FontFamily=new FontFamily("Segoe Fluent Icons"),FontSize=21,VerticalAlignment=VerticalAlignment.Center,Foreground=Brush("#5887E8")};body.Children.Add(glyph);
   var text=new StackPanel{Margin=new Thickness(8,0,10,0)};Grid.SetColumn(text,1);body.Children.Add(text);var title=Label(name,13);title.FontWeight=FontWeights.SemiBold;title.TextWrapping=TextWrapping.NoWrap;title.TextTrimming=TextTrimming.CharacterEllipsis;text.Children.Add(title);
   BatteryGauge[] gauges;var battery=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,7,0,0)};text.Children.Add(battery);if(batteryViews.TryGetValue(id,out gauges)){foreach(var source in gauges){var label=Label(source.Label,11,"697386");label.VerticalAlignment=VerticalAlignment.Center;label.Margin=new Thickness(0,0,3,0);battery.Children.Add(label);battery.Children.Add(new BatteryGauge{Level=source.Level,Width=38,Height=24,Margin=new Thickness(0,0,8,0)});}}else battery.Children.Add(Label(L("电量暂不可用","Battery unavailable"),11,"8A94A5"));
   var state=Label(status,11,"258262");state.VerticalAlignment=VerticalAlignment.Top;state.Margin=new Thickness(0,2,0,0);Grid.SetColumn(state,2);body.Children.Add(state);
   var button=Button("",()=>{CloseTrayPanel();action();});button.Content=body;button.HorizontalContentAlignment=HorizontalAlignment.Stretch;button.Padding=new Thickness(10,12,10,12);button.Margin=new Thickness(0,0,0,6);button.ToolTip=name;host.Children.Add(button);
  }
  Window BuildTrayPanel(){
   var w=new Window{Width=384,SizeToContent=SizeToContent.Height,WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=Brushes.Transparent,ShowInTaskbar=false,ResizeMode=ResizeMode.NoResize,Topmost=true};foreach(var key in Window.Resources.Keys)w.Resources[key]=Window.Resources[key];
   var stack=new StackPanel();var header=new DockPanel{Margin=new Thickness(2,0,0,12)};var gear=TrayAction("",0xE713,()=>{Show();Navigate("General");});gear.Width=38;gear.Padding=new Thickness(0);gear.ToolTip=L("通用设置","General settings");gear.Content=new TextBlock{Text="\uE713",FontFamily=new FontFamily("Segoe Fluent Icons"),FontSize=17,Foreground=Brush("#A77AE3")};DockPanel.SetDock(gear,Dock.Right);header.Children.Add(gear);var open=Button("AirBridge",()=>{CloseTrayPanel();Show();});open.FontSize=17;open.FontWeight=FontWeights.SemiBold;open.Background=Brushes.Transparent;open.HorizontalAlignment=HorizontalAlignment.Left;header.Children.Add(open);stack.Children.Add(header);
   var devices=new StackPanel();foreach(var source in phones.Sources.Where(p=>!Ignored(p.Id))){string id=source.Id;TrayDevice(devices,source.Name,phones.Get(id).Connected?L("● 已连接","● Connected"):L("未连接","Disconnected"),0xE8EA,id,()=>Run(async()=>{await TogglePhoneConnection(id);}));}
   if(inventory!=null){var current=inventory.Devices.FirstOrDefault(d=>d.IsDefault);if(current!=null)TrayDevice(devices,current.DisplayName,L("● 当前输出","● Current output"),0xE7F6,current.Id,()=>{if(current.IsLocal){Show();Navigate("Devices");}else ToggleHeadset(current);});}
   if(devices.Children.Count==0)devices.Children.Add(Label(L("暂无可用设备","No available devices"),13,"8A94A5"));stack.Children.Add(new ScrollViewer{Content=devices,MaxHeight=240,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled});
   if(inventory!=null){var outputs=inventory.Endpoints.Where(p=>p.Active).ToArray();if(outputs.Length>0){var choice=new ComboBox{Name="TrayOutputPicker",Height=36,ItemsSource=outputs.Select(p=>String.IsNullOrWhiteSpace(p.Name)?L("未命名输出设备","Unnamed output device"):p.Name).ToArray(),SelectedIndex=Array.FindIndex(outputs,p=>p.IsDefault),Margin=new Thickness(0,3,0,0),ToolTip=L("切换输出设备","Switch output device")};choice.SelectionChanged+=(s,e)=>{var selected=choice.SelectedIndex;if(selected<0)return;try{OutputSwitch.Select(outputs[selected].Id);StartInventory();CloseTrayPanel();}catch(Exception ex){Error(ex);}};stack.Children.Add(choice);}}
   TrayRule(stack);stack.Children.Add(Label(L("快捷入口","Quick access"),11,"8A94A5"));var shortcuts=new System.Windows.Controls.Primitives.UniformGrid{Columns=2,Margin=new Thickness(0,8,0,0)};var audio=TrayAction(L("音频管理","Audio routing"),0xE767,()=>{Show();Navigate("Audio");});audio.Margin=new Thickness(5,0,0,0);var device=TrayAction(L("设备管理","Devices"),0xE7F6,()=>{Show();Navigate("Devices");});device.Margin=new Thickness(0,0,5,0);shortcuts.Children.Add(device);shortcuts.Children.Add(audio);stack.Children.Add(shortcuts);
   TrayRule(stack);var switches=new StackPanel();var reconnect=new CheckBox{Content=L("自动重连","Auto reconnect"),IsChecked=settings.Bool("AutoConnect"),FontSize=12,Margin=new Thickness(0)};reconnect.Click+=(s,e)=>{phones.SetAutoConnect(reconnect.IsChecked==true);U<CheckBox>("AutoConnect").IsChecked=reconnect.IsChecked;};reconnect.SetResourceReference(FrameworkElement.StyleProperty,"TraySwitch");switches.Children.Add(reconnect);var startup=new CheckBox{Content=L("开机自启","Start at login"),IsChecked=File.Exists(StartupPath),FontSize=12,Margin=new Thickness(0)};startup.Click+=(s,e)=>{try{SetStartup(startup.IsChecked==true);U<CheckBox>("Startup").IsChecked=startup.IsChecked;}catch(Exception ex){startup.IsChecked=File.Exists(StartupPath);Error(ex);}};startup.SetResourceReference(FrameworkElement.StyleProperty,"TraySwitch");switches.Children.Add(startup);stack.Children.Add(switches);TrayRule(stack);
   var exit=TrayAction(L("退出 AirBridge","Exit AirBridge"),0xE7E8,Exit);exit.HorizontalAlignment=HorizontalAlignment.Left;exit.Background=Brushes.Transparent;var exitGlyph=(TextBlock)((StackPanel)exit.Content).Children[0];exitGlyph.Foreground=Brush("#8A94A5");exit.MouseEnter+=(s,e)=>exitGlyph.Foreground=Brush("#CE7585");exit.MouseLeave+=(s,e)=>exitGlyph.Foreground=Brush("#8A94A5");stack.Children.Add(exit);
   var frame=new Border{Child=stack,Padding=new Thickness(18),Margin=new Thickness(12),CornerRadius=new CornerRadius(16),BorderThickness=new Thickness(1),Effect=new System.Windows.Media.Effects.DropShadowEffect{BlurRadius=20,Opacity=.18,ShadowDepth=4}};frame.SetResourceReference(Border.BackgroundProperty,"Brush_FFFFFF");frame.SetResourceReference(Border.BorderBrushProperty,"Brush_E8EBF0");w.Content=frame;Motion.Attach(w);return w;
  }
 }
}
